#!/bin/bash

# FRFD Document Downloader
# Downloads all documents from filerfireandrescue.org organized by folder

BASE="https://www.filerfireandrescue.org"
OUT="$HOME/FRFD-Documents"

mkdir -p "$OUT/Board-Meetings/2023"
mkdir -p "$OUT/Board-Meetings/2024"
mkdir -p "$OUT/Board-Meetings/2025"
mkdir -p "$OUT/Board-Meetings/2026"
mkdir -p "$OUT/Financial"
mkdir -p "$OUT/Legal"
mkdir -p "$OUT/Images"

echo "📁 Downloading to $OUT"
echo ""

dl() {
  local url="$1"
  local dest="$2"
  local label="$3"
  echo "⬇️  $label"
  curl -sL "$url" -o "$dest" && echo "   ✅ Saved: $dest" || echo "   ❌ FAILED: $url"
}

